<script setup lang="ts">
import type { StudentEditData, StudentSaveRequest } from '../api/contracts';import CodeSelect from './CodeSelect.vue';import JapaneseBirthDateField from './JapaneseBirthDateField.vue';const props=defineProps<{ data:StudentEditData; busy:boolean }>();const emit=defineEmits<{ options:[]; 'update:form':[value:StudentSaveRequest] }>();
const texts=[{key:'studentName',label:'氏名 ※必須',id:'REG-003',limit:16,required:true},{key:'studentNameKana',label:'氏名カナ ※必須',id:'REG-004',limit:72,required:true},{key:'postalCode',label:'郵便番号 ※必須',id:'REG-007',limit:20,required:true},{key:'addressLine1',label:'住所1 ※必須',id:'REG-009',limit:90,required:true},{key:'addressLine2',label:'住所2',id:'REG-010',limit:90},{key:'phoneNumber',label:'本人電話',id:'REG-011',limit:40},{key:'emailAddress',label:'本人メール',id:'REG-012',limit:120},{key:'emergencyContactName',label:'緊急連絡先氏名',id:'REG-020',limit:16},{key:'emergencyPhoneNumber',label:'緊急連絡先電話',id:'REG-022',limit:40}] as const;
function change<K extends keyof StudentSaveRequest>(key:K,value:StudentSaveRequest[K]){emit('update:form',{...props.data.form,[key]:value});} function setText(key:typeof texts[number]['key'],event:Event){change(key,(event.target as HTMLInputElement).value);}
function classChanged(){const c=props.data.classes.find(c=>c.classId===props.data.form.classId);if(c){emit('update:form',{...props.data.form,schoolYear:c.schoolYear,gradeCode:c.gradeCode});}}
</script>
<template><fieldset :disabled="busy || !data.permissions.update"><legend>学生基本情報</legend><div class="fields"><label>学籍番号 ※必須<input id="REG-002" :value="data.form.studentNo || ''" @input="change('studentNo',($event.target as HTMLInputElement).value)" :readonly="data.studentId!==null" maxlength="30" required></label><label v-for="field in texts" :key="field.key">{{field.label}}<input :id="field.id" :value="data.form[field.key] || ''" :maxlength="field.limit" :required="'required' in field && field.required" @input="setText(field.key,$event)"></label><JapaneseBirthDateField :model-value="data.form.birthDateInput" @update:model-value="change('birthDateInput',$event)"/><label>性別 ※必須<CodeSelect id="REG-006" :model-value="data.form.genderCode" @update:model-value="change('genderCode',$event || '')" :items="data.codes" category="GENDER" required/></label><label>都道府県 ※必須<CodeSelect id="REG-008" :model-value="data.form.prefectureCode" @update:model-value="change('prefectureCode',$event || '')" :items="data.codes" category="PREFECTURE" required/></label><label>入学日 ※必須<input id="REG-013" :value="data.form.admissionDate || ''" @input="change('admissionDate',($event.target as HTMLInputElement).value)" type="date" required @change="$emit('options')"></label><label>在籍区分 ※必須<CodeSelect id="REG-014" :model-value="data.form.enrollmentStatusCode" @update:model-value="change('enrollmentStatusCode',$event || ''); $emit('options')" :items="data.codes" category="ENROLLMENT_STATUS" required/></label><label>卒業・退学日<input id="REG-015" :value="data.form.enrollmentEndDate || ''" @input="change('enrollmentEndDate',($event.target as HTMLInputElement).value)" type="date" @change="$emit('options')"></label><label>年度<select id="REG-016" :value="data.form.schoolYear ?? ''" @change="change('schoolYear',($event.target as HTMLSelectElement).value ? Number(($event.target as HTMLSelectElement).value) : null); $emit('options')"><option value="">未指定</option><option v-for="y in Array.from(new Set([...data.years,...(data.form.schoolYear===null?[]:[data.form.schoolYear])])).sort((a,b)=>b-a)" :key="y" :value="y">{{y}}</option></select></label><label>学年<CodeSelect id="REG-017" :model-value="data.form.gradeCode" @update:model-value="change('gradeCode',$event); $emit('options')" :items="data.codes" category="GRADE"/></label><label>クラス<select id="REG-018" :value="data.form.classId || ''" @change="change('classId',($event.target as HTMLSelectElement).value || null); classChanged()"><option value="">未所属</option><option v-for="c in data.classes" :key="c.classId" :value="c.classId" :disabled="!c.selectable && c.classId!==data.form.classId">{{c.schoolYear}} {{c.gradeName}} {{c.classCode}} {{c.className}} {{c.note}}</option></select><small v-if="data.form.classId">人数 {{data.classes.find(c=>c.classId===data.form.classId)?.occupancy ?? '－'}}／定員 {{data.classes.find(c=>c.classId===data.form.classId)?.capacity ?? '制限なし'}}（参考）</small></label><label>緊急連絡先続柄<CodeSelect id="REG-021" :model-value="data.form.relationshipCode" @update:model-value="change('relationshipCode',$event)" :items="data.codes" category="RELATIONSHIP"/></label><label class="full">備考<textarea id="REG-023" :value="data.form.remarks || ''" @input="change('remarks',($event.target as HTMLInputElement).value)" maxlength="240"></textarea></label><label class="full">確認・変更理由<textarea id="REG-024" :value="data.form.operationReason || ''" @input="change('operationReason',($event.target as HTMLInputElement).value)" maxlength="120"></textarea></label></div><p>本人電話・メール・緊急電話のいずれか1つ以上。緊急連絡先は3項目をすべて入力してください。</p></fieldset></template>
